"""ObsidianUI-informed presentation, adapted to the existing vanilla-JS console.

Source: https://github.com/Atharvsinh-codez/ObsidianUI (MIT).
This additive layer never changes API payloads, credentials, billing or collection.
"""

CSS = r'''
/* ObsidianUI Dashboard Shell / Analytics Dashboard palette and motion. */
:root{--ink:#18181b;--text:#18181b;--muted:#62626b;--line:#e7e7eb;--bg:#f6f6f7;--blue:#2563eb;--sf-surface:#fff;--sf-hover:#f0f0f2;--sf-radius:12px;--sf-ease:cubic-bezier(.22,1,.36,1)}
body{background:var(--bg);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;font-size:13px;line-height:1.65}
*{scrollbar-width:thin;scrollbar-color:#d4d4da transparent}::selection{background:#dbeafe;color:#18181b}
.shell{grid-template-columns:224px minmax(0,1fr)}#workbenchNav{background:#fafafa;padding:22px 12px 14px;border-right:1px solid var(--line)}
.brand{font-size:19px;margin:0 12px 26px;gap:10px;letter-spacing:-.5px}.brand small{font-size:10px;color:#71717a;margin-top:3px;font-weight:400}.brand-mark{position:relative;isolation:isolate;width:32px;height:32px;border-radius:9px;background:#202023;box-shadow:0 1px 2px #0002;color:white;font-size:19px;overflow:hidden}.brand-mark:after{content:"";position:absolute;inset:0;z-index:-1;background:conic-gradient(from 35deg,#ffffff28,transparent 22%,#ffffff40 28%,transparent 40%,#7da9ff55 60%,transparent 70%);clip-path:polygon(0 0,100% 0,70% 100%,20% 80%)}
#workbenchNav nav{gap:3px}#workbenchNav nav a{border-radius:7px;margin:0;min-height:39px;padding:8px 12px;gap:11px;font-size:12px;color:#5c5c65;transition:background 150ms,color 150ms,box-shadow 150ms}#workbenchNav nav a:hover{background:#eeeef1;color:#18181b}#workbenchNav nav a[aria-current=page]{background:#fff;color:#18181b;box-shadow:0 0 0 1px #e4e4e7,0 2px 3px #00000005;font-weight:650}.nav-icon,.nav-icon .mi{width:18px;height:18px}.nav-section{font-size:10px;letter-spacing:.05em;padding:19px 12px 7px;color:#86868e}.aside-foot{font-size:10px;margin:20px 12px 0;padding-top:16px}.aside-foot a{color:#52525b}#workbenchNav>form{margin:12px!important}#workbenchNav>form button{font-size:11px;min-height:32px;background:transparent;box-shadow:none}
main#mainContent{padding:27px 36px 40px;max-width:1640px;width:100%;min-width:0;box-sizing:border-box}.top{padding-bottom:20px;border-bottom:1px solid var(--line);margin-bottom:12px}h1#pageTitle{font-size:24px;letter-spacing:-.8px;font-weight:650;line-height:1.3}#pageSubtitle{font-size:11px;margin-top:7px;color:#71717a}.top-tools{gap:9px}.global-search{min-width:168px;min-height:35px;font-size:11px;background:white!important;border-color:var(--line);border-radius:7px}.global-search kbd{font-size:10px;color:#85858e;background:#f6f6f7;border:1px solid #e4e4e7;padding:1px 4px}.top-tools>.button-link{font-size:11px;min-height:35px;border-radius:7px;padding:7px 12px;background:#202023;border:1px solid #202023;color:white;box-shadow:inset 0 1px #ffffff15,0 1px 2px #0001}.top-tools .mi{width:16px;height:16px}.access-strip{font-size:10px;margin:0 0 24px;color:#71717a}.access-strip a{color:#62626b}.collector-indicator{font-size:10px}
button,.button-link{font:inherit;font-size:12px;min-height:37px;border-radius:7px;background:#242427;border-color:#242427;color:white;box-shadow:inset 0 1px #ffffff12,0 1px 2px #00000008;transition:background 150ms,box-shadow 150ms,transform 150ms}button:hover,.button-link:hover{background:#3e3e44;border-color:#3e3e44}button:active:not(:disabled),.button-link:active{transform:translateY(1px)}button.secondary,.button-link.secondary{background:#fff;color:#414149;border-color:#dedee4;box-shadow:0 1px 2px #00000005}button.secondary:hover,.button-link.secondary:hover{background:#f7f7f8;border-color:#c8c8d0}button.mini{min-height:30px;font-size:11px;padding:5px 10px}.icon-button{box-shadow:none}button:disabled{opacity:.45;transform:none!important}
:where(button,a,input,select,textarea,summary,[tabindex]):focus-visible{outline:2px solid #2563eb;outline-offset:3px}input:not([type=checkbox]):not([type=radio]),select,textarea{background:#fff;color:#27272a;border:1px solid #dedee4;border-radius:7px;min-height:39px;font:inherit;font-size:12px;padding:9px 11px;box-shadow:0 1px 2px #00000004;max-width:100%;box-sizing:border-box}input:not([type=checkbox]):not([type=radio]):focus,select:focus,textarea:focus{outline:2px solid #2563eb20;outline-offset:0;border-color:#8aabf4}input::placeholder,textarea::placeholder{color:#93939d}label{color:#52525b;font-weight:500;font-size:11px}input[type=checkbox],input[type=radio]{accent-color:#27272a}label:has(input:checked){border-color:#a1a1aa}
.panel{border:1px solid var(--line);border-radius:var(--sf-radius);padding:23px;background:white;box-shadow:0 2px 3px #00000002;margin-bottom:18px}.section-head{gap:14px}.section-head h2,.source-hub h2{font-size:15px;letter-spacing:-.3px;font-weight:650}.panel h2{font-size:17px;letter-spacing:-.35px}.panel h3{font-size:14px}.help,.product-panel-head p{color:#71717a;font-size:11px;line-height:1.8}.product-panel-head{margin-bottom:20px}.product-panel-head h2{font-size:20px}.badge,.source-supported{font-size:10px;border-radius:5px}.notice{border-color:#dbe4f4;background:#f3f6fd;color:#334d7c;border-radius:9px}.notice.error{background:#fff4f3;border-color:#f0ceca;color:#b3261e}.product-code{font:11px/1.8 ui-monospace,SFMono-Regular,Menlo,monospace;background:#fafafa;border-color:#e7e7eb;border-radius:8px;padding:15px;white-space:pre-wrap;overflow-wrap:anywhere}
details>summary{list-style:none;display:flex;align-items:center;gap:10px;cursor:pointer;font-size:12px;font-weight:550;color:#52525b}details>summary::-webkit-details-marker{display:none}details>summary:after{content:"›";font-size:20px;line-height:1;margin-left:auto;color:#a1a1aa;transition:transform 180ms}details[open]>summary:after{transform:rotate(90deg)}details.panel>summary{min-height:24px}details[open].panel>summary{padding-bottom:16px;border-bottom:1px solid #f0f0f2;margin-bottom:18px}.quick-options,.analysis-advanced{background:#fafafa;border:1px solid var(--line);border-radius:8px;padding:13px 14px}.quick-options[open]>summary{margin-bottom:14px}.quick-options .quick-grid{margin-top:0}
/* Split Showcase, V-prism and Parallax Slider: small, local, non-WebGL adaptations. */
.system-flow{position:relative;overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:12px;padding:23px 26px;margin-bottom:25px}.system-flow:before{content:"";position:absolute;right:-40px;top:-80px;width:260px;height:220px;pointer-events:none;background:linear-gradient(135deg,transparent 35%,#f3f5fa 35%,#fafbfe 62%,transparent 62%);opacity:.8}.system-flow-head{position:relative}.system-flow-head h2{font-size:15px;color:#27272a}.system-flow-head p{font-size:11px;color:#71717a}.system-flow-badge{background:#f4f4f5;color:#71717a;border:1px solid #e7e7eb;border-radius:5px;font-size:9px}.system-flow-stage{margin:20px 0 16px;gap:0}.system-flow-node{background:#fafafa;border:1px solid #e7e7eb;border-radius:9px;box-shadow:none;min-width:0;padding:17px 16px}.system-flow-node b{font-size:13px;color:#3f3f46}.system-flow-node span{font-size:10px;color:#8a8a94}.system-flow-node.primary{background:#242427;border-color:#242427}.system-flow-node.primary b{color:#fff}.system-flow-node.primary span{color:#c4c4cc}.system-flow-node.primary i{background:#8db5ff}.system-flow-link-label{font-size:9px;color:#8a8a94}.system-flow-source{font-size:10px;color:#8a8a94}.system-flow-node.optional{background:#fafafa}.source-hub{margin-bottom:24px}.source-hub-head{margin-bottom:13px}.source-hub-head>span{font-size:10px}.source-entries{grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.source-entry{position:relative;min-height:112px;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;padding:17px 15px;background:white;border:1px solid var(--line);border-radius:10px;gap:11px;box-shadow:0 1px 2px #00000003;transition:transform 200ms var(--sf-ease),box-shadow 200ms,border-color 200ms;text-decoration:none;color:#27272a}.source-entry:hover{background:#fff;border-color:#b6c7eb;box-shadow:0 5px 18px #18181b08;transform:translateY(-3px)}.source-entry strong{font-size:12px;color:#3f3f46}.source-entry small{font-size:10px;line-height:1.65;color:#80808b;margin-top:4px}.source-entry .google-source-icon{width:25px;height:25px}.source-entry>.mi{position:absolute;right:13px;top:20px;width:14px;height:14px;color:#a1a1aa}.source-supported{padding:0 4px;background:#f0f8f2;color:#287343;font-size:8px;line-height:1.8}.source-maps strong{display:flex!important;gap:4px;align-items:center}.archive-summary{border:1px solid var(--line);border-radius:10px;margin-top:15px;padding:20px 0;background:white}.archive-summary strong{font-size:27px;font-weight:550;letter-spacing:-1px;color:#27272a}.archive-summary span{font-size:10px}.archive-summary>div{padding:0 22px}.archive-note{font-size:10px;color:#8a8a94;line-height:1.8}.workbench-health{padding:13px 18px}.workbench-health summary{font-size:11px}
/* Analytics Dashboard data tables and metrics, using the existing real data. */
.result{background:white;border:1px solid var(--line);border-radius:10px;padding:20px 23px;transition:border-color 150ms}.result:hover{border-color:#c4c4ce}.result h3{font-size:15px;line-height:1.7}.result h3 a{color:#334d79}.result p{font-size:12px}.record-facts{font-size:11px}.result-meta{font-size:10px}.result-meta .badge{font-size:10px}.table-scroll,.table-wrap{border:1px solid var(--line);border-radius:9px;overflow:auto}table{border-collapse:collapse;font-size:12px}thead{background:#fafafa}th{font-size:10px;letter-spacing:.02em;color:#71717a;font-weight:550;white-space:nowrap}td,th{border-bottom:1px solid #ededf0;padding:12px 14px}tbody tr:hover{background:#fafafa}.analysis-tabs,.view-tools,#insightsView .tabs{gap:4px;padding:4px;background:#eeeef0;border:1px solid #e7e7eb;border-radius:8px;width:fit-content;max-width:100%;flex-wrap:wrap}.analysis-tabs button,.view-tools button,#insightsView .tabs button{box-shadow:none;border:1px solid transparent;background:transparent;color:#71717a;border-radius:5px;font-size:11px;min-height:30px;padding:5px 11px}.analysis-tabs button[aria-selected=true],.view-tools button[aria-pressed=true],#insightsView .tabs button[aria-selected=true]{background:#fff;color:#27272a;border-color:#e4e4e7;box-shadow:0 1px 2px #00000007}.analysis-kpi,.product-stat,#insightsView .stat{border-color:var(--line);border-radius:9px;background:#fff}.analysis-chart,.product-chart{border-color:var(--line);background:#fafafa}.analysis-applied{border-color:var(--line);background:#fafafa;color:#71717a}.analysis-filter-grid{gap:14px}.report-skeleton>div{background:linear-gradient(100deg,#f0f0f2 20%,#f8f8fa 50%,#f0f0f2 80%);background-size:220% 100%;animation:sf-shimmer 2s ease infinite}
/* Dashboard Shell segmented controls and Split Showcase request/results. */
.quick-modes{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;padding:5px;background:#f4f4f5;border:1px solid #ededf0;border-radius:10px;margin:22px 0 18px}.quick-modes button{display:block;min-width:0;min-height:66px;border:1px solid transparent;background:transparent;color:#62626b;border-radius:6px;padding:11px 13px;font-size:12px;box-shadow:none}.quick-modes button span{display:block;margin-top:5px;font-weight:400;font-size:10px;line-height:1.6;color:#8a8a94}.quick-modes button:hover{background:#eeeef0;border-color:transparent}.quick-modes button[aria-pressed=true]{background:#fff;border-color:#dedee4;box-shadow:0 2px 4px #00000005;color:#202023}.quick-steps{margin:18px 0 24px;gap:0;border-bottom:1px solid #ededf0;padding-bottom:16px}.quick-steps li{background:transparent;color:#9a9aa3;border-radius:0;font-size:10px;padding:0 15px 0 0}.quick-steps li+li:before{content:"/";padding-right:15px;color:#d4d4da}.quick-steps li[aria-current=step]{background:transparent;color:#27272a;font-weight:650}.quick-source-grid{gap:8px}.quick-source-grid label{padding:12px 11px;border-radius:8px;background:#fff;transition:background 150ms,border-color 150ms}.quick-source-grid label:has(input:checked){background:#fafafa;border-color:#a1a1aa}.quick-source-grid strong{font-size:11px}.quick-source-grid small{font-size:10px;color:#8a8a94}.quick-source-grid input{accent-color:#27272a}.quick-panel label{font-size:11px}.quick-panel textarea{font-size:12px;min-height:112px;border-color:#dedee4;background:#fafafa}.quick-summary{border-top-color:#ededf0;gap:16px}.quick-summary strong{font-size:12px}.quick-summary p{font-size:10px;max-width:52ch}.quick-status{font-size:11px;border:1px solid #e7e7eb;background:#fafafa;padding:12px 14px;border-radius:8px;display:flex;gap:9px;align-items:flex-start;line-height:1.8}.quick-status:before{content:"";width:6px;height:6px;min-width:6px;background:#92929e;border-radius:50%;margin-top:7px}.quick-status[data-error=true]{border-color:#f0ceca;background:#fff5f4;color:#b3261e}.quick-status[data-error=true]:before{background:#b3261e}.quick-record{border-color:#e7e7eb;border-radius:9px;background:white;padding:19px}.quick-record h3{font-size:13px}.quick-record-meta{color:#8a8a94;font-size:10px}.quick-row h4{font-size:13px}.quick-row p{font-size:11px}.quick-download{padding-top:15px;border-top:1px solid #ededf0}.quick-queue{padding:0;margin:12px 0}.quick-queue>div{position:relative;padding:11px 12px 11px 27px;border:1px solid #e7e7eb;background:#fafafa;border-radius:7px;font-size:11px;margin:6px 0}.quick-queue>div:before{content:"";position:absolute;top:18px;left:12px;width:5px;height:5px;background:#9a9aa4;border-radius:50%}.quick-queue>div[data-sf-state=done]:before{background:#16a34a}.quick-queue>div[data-sf-state=error]:before{background:#dc2626}.quick-queue>div[data-sf-state=busy]:before{background:#2563eb;animation:sf-pulse 1.6s ease-in-out infinite}#sfRequestLayout{display:grid;grid-template-columns:minmax(0,1fr);gap:0;align-items:start}#sfRequestLayout>div{min-width:0}#sfRequestLayout:has(#quickOutput:not([hidden])){grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:26px}#sfRequestLayout #quickOutput{margin-top:0;min-width:0;border-left:1px solid var(--line);padding-left:25px}#sfRequestLayout .quick-input-grid{grid-template-columns:minmax(0,1fr)}#sfRequestLayout:not(:has(#quickOutput:not([hidden]))) .quick-input-grid{grid-template-columns:2fr 1fr}#sfRequestLayout:has(#quickOutput:not([hidden])) .quick-source-grid{grid-template-columns:1fr 1fr}#sfRequestLayout #quickOutput>details{margin-top:18px}
/* Discover Button: the original expanding fill, adapted to the current CTA. */
.sf-discover{position:relative;isolation:isolate;overflow:hidden;background:#f4f4f5!important;color:#27272a!important;border:1px solid #dedee4!important;border-radius:8px!important;padding:10px 19px 10px 42px!important;min-height:41px!important}.sf-discover:before{content:"→";position:absolute;left:4px;top:4px;bottom:4px;width:30px;display:grid;place-items:center;background:#242427;color:white;border-radius:5px;z-index:-1;transition:width 400ms cubic-bezier(.65,0,.076,1);text-indent:0}.sf-discover:hover,.sf-discover:focus-visible{color:white!important}.sf-discover:hover:before,.sf-discover:focus-visible:before{width:calc(100% - 8px);text-indent:-75%}.sf-discover:disabled{opacity:.5}.maps-form-grid,.maps-location-grid{gap:13px}#mapsResults article{border:1px solid #e7e7eb;border-radius:9px;padding:18px;margin:12px 0;background:white}#mapsResults h3{font-size:14px}#mapsResults table{font-size:11px}#mapsCapability{font-size:10px;color:#8a8a94}
/* Art Gallery and Hover Image: opt-in thumbnails stay opt-in. */
.sf-gallery-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:0 0 14px}.sf-gallery-tools .help{margin-right:auto}.sf-gallery-tools button{min-height:30px;font-size:10px;padding:4px 10px}.sf-gallery-tools button[aria-pressed=true]{background:#27272a;color:#fff;border-color:#27272a}#resultRows.sf-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}#resultRows.sf-gallery .result{margin:0;min-width:0}#resultRows.sf-gallery .result.images{contain:layout}#resultRows .result.images img{width:100%;max-height:240px!important;object-fit:contain;background:#f5f5f7;border-radius:7px;transition:transform 400ms var(--sf-ease)}@media(hover:hover){#resultRows.sf-gallery .result.images img:hover{transform:scale(1.025)}}
.sf-source-controls{display:none;gap:5px}.sf-source-controls button{width:29px;min-height:29px;padding:0;font-size:15px}.sf-shortcuts{border-top:1px solid var(--line);display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:13px 18px}.sf-shortcuts a{color:#62626b;background:#f6f6f7;font-size:11px;padding:8px 9px;border-radius:5px;text-decoration:none;text-align:center}.sf-shortcuts a:hover{background:#eeeef0;color:#18181b}.search-dialog{border-color:#dedee4;border-radius:12px;box-shadow:0 24px 80px #18181b22}.search-dialog-foot{background:#fafafa}.sf-motion-toggle{font-size:11px;color:#71717a;display:flex;align-items:center;gap:8px;margin-top:8px}.sf-motion-toggle input{width:14px!important;height:14px!important}.sf-collapse{width:100%;text-align:left;justify-content:flex-start;background:transparent!important;color:#8a8a94!important;border:0!important;box-shadow:none;padding:6px 12px;min-height:31px;font-size:10px}.sf-collapse .mi{width:15px;height:15px}.sf-flip{animation:sf-flip-in 240ms var(--sf-ease)}.sf-updated{animation:sf-number-in 300ms var(--sf-ease)}.sf-text-enter{animation:sf-stream-in 280ms var(--sf-ease)}.foot{border-color:var(--line);color:#9a9aa4;font-size:9px}
@keyframes sf-flip-in{from{opacity:.4;transform:perspective(600px) rotateX(-18deg) translateY(3px)}to{opacity:1;transform:none}}@keyframes sf-number-in{from{opacity:.4;transform:translateY(4px)}to{opacity:1;transform:none}}@keyframes sf-stream-in{from{opacity:.4;transform:translateY(6px)}to{opacity:1;transform:none}}@keyframes sf-pulse{50%{opacity:.35}}@keyframes sf-shimmer{to{background-position:-220% 0}}
@media(min-width:1101px){body.sf-nav-compact .shell{grid-template-columns:72px minmax(0,1fr)}body.sf-nav-compact .brand{margin:0 auto 26px;justify-content:center}body.sf-nav-compact .brand-name,body.sf-nav-compact .nav-section,body.sf-nav-compact .aside-foot,body.sf-nav-compact #workbenchNav>form,body.sf-nav-compact .sf-collapse span{display:none}body.sf-nav-compact #workbenchNav nav a{font-size:0;justify-content:center;gap:0;padding:10px}body.sf-nav-compact #workbenchNav nav a .nav-icon{font-size:12px}body.sf-nav-compact .sf-collapse{justify-content:center}body.sf-nav-compact #workbenchNav{padding-inline:12px}body.sf-nav-compact .sf-collapse svg{transform:rotate(180deg)}}
@media(max-width:1200px){main#mainContent{padding:25px}.source-entries{grid-template-columns:repeat(3,minmax(0,1fr))}.source-entry{min-height:100px}.quick-modes button{padding:10px}.quick-modes button span{font-size:9px}#sfRequestLayout:has(#quickOutput:not([hidden])){grid-template-columns:1fr;gap:24px}#sfRequestLayout #quickOutput{border-left:0;border-top:1px solid var(--line);padding:22px 0 0}}
@media(max-width:760px){.shell{display:block}main#mainContent{padding:20px 16px 32px}#workbenchNav{padding-top:24px;transition:none;overflow-anchor:none;scroll-behavior:auto}.top{align-items:flex-start;gap:8px;padding-bottom:16px}.top-title{gap:8px;min-width:0}h1#pageTitle{font-size:21px}#pageSubtitle{font-size:10px;max-width:25ch}.top-tools{gap:5px;flex-shrink:0}.top-tools>.button-link{min-height:34px;padding:7px 9px}.global-search{min-width:34px!important;width:34px!important;padding:0!important}.global-search>span,.global-search kbd{display:none}.global-search:before{content:"⌕";font:22px/1 system-ui}.access-strip{font-size:9px;margin-bottom:18px;gap:8px}.access-strip a .mi{display:none}.panel{padding:18px 16px;border-radius:10px}.system-flow{padding:18px 16px}.system-flow-head{gap:8px}.system-flow-head p{font-size:10px}.system-flow-badge{display:none}.system-flow-node{padding:14px}.system-flow-node b{font-size:12px}.source-entries{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:10px;padding:2px 1px 12px;overscroll-behavior-inline:contain;touch-action:pan-x pan-y;cursor:grab}.source-entry{flex:0 0 155px;min-height:110px;scroll-snap-align:start;user-select:none}.source-entry:hover{transform:none}.source-hub-head{flex-wrap:wrap}.source-hub-head>span{font-size:9px}.sf-source-controls{display:flex;margin-left:auto}.source-hub-head>.sf-source-controls{order:1}.source-hub-head>span{order:2;flex-basis:100%}.archive-summary{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 0;padding:17px 0}.archive-summary>div{padding:0 16px}.archive-summary>div:nth-child(2){border-right:0}.archive-summary strong{font-size:23px}.archive-summary span{font-size:9px}.archive-note{font-size:9px}.quick-modes{grid-template-columns:repeat(2,minmax(0,1fr));gap:4px;padding:4px;margin-top:16px}.quick-modes button{font-size:11px;min-height:60px;padding:10px}.quick-steps li{font-size:9px;padding-right:8px}.quick-steps li+li:before{padding-right:8px}.quick-steps{margin:15px 0 20px;gap:5px}.quick-source-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.quick-source-grid label{padding:10px}.quick-input-grid,#sfRequestLayout:not(:has(#quickOutput:not([hidden]))) .quick-input-grid{grid-template-columns:1fr}.quick-summary{align-items:flex-start;flex-direction:column;gap:12px}.quick-summary button{width:100%}.quick-summary p{font-size:10px}.quick-locale,.quick-grid{gap:11px}.quick-record{padding:14px}.quick-download{gap:8px}.quick-status{font-size:10px;padding:10px 12px}.quick-panel label{font-size:10px}.maps-form-grid,.maps-location-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.maps-form-grid>label:first-child{grid-column:1/-1}.sf-collapse{display:none}.result{padding:17px}.result h3{font-size:14px}.result p{font-size:11px}#resultRows.sf-gallery{grid-template-columns:1fr}.sf-shortcuts{gap:5px;padding:12px}.sf-shortcuts a{font-size:10px;padding:7px}.sf-gallery-tools .help{flex-basis:100%}.search-dialog{width:calc(100vw - 24px)}.search-dialog-head{padding:12px}.search-dialog input{font-size:12px}.search-dialog-foot{padding:12px}.source-cards{grid-template-columns:1fr!important}.maps-location-grid input{min-width:0}#insightsView .stats{gap:12px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
body.sf-reduced-motion *,body.sf-reduced-motion *::before,body.sf-reduced-motion *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}
[hidden]{display:none!important}
'''

JS = r'''
/* All behavior here is presentation-only. No fetching, submission or telemetry. */
(()=>{'use strict';
 if(document.documentElement.dataset.sfUi==='obsidian-1')return;
 document.documentElement.dataset.sfUi='obsidian-1';
 const byId=id=>document.getElementById(id);
 const reduce=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('sf-reduced-motion');
 const animate=(node,cls)=>{if(!node||reduce()||node.hidden)return;node.classList.remove(cls);requestAnimationFrame(()=>{node.classList.add(cls);setTimeout(()=>node.classList.remove(cls),420)});};
 // Dashboard Shell: group navigation without changing routes or their selection owner.
 const nav=document.querySelector('#workbenchNav nav');
 if(nav){const groups=[['采集与数据',['overview','tasks','results','maps','research']],['分析与监测',['insights','analysis','monitors']],['开发与管理',['api','capability','whale','settings']]];const links=[...nav.querySelectorAll('a[data-view]')];nav.querySelectorAll('.nav-section').forEach(n=>n.remove());for(const [label,keys]of groups){const h=document.createElement('span');h.className='nav-section';h.textContent=label;nav.append(h);for(const key of keys){const a=links.find(a=>a.dataset.view===key);if(a){a.title=a.textContent.trim();nav.append(a);}}} }
 const aside=byId('workbenchNav');
 if(aside){const b=document.createElement('button');b.type='button';b.className='sf-collapse';b.id='sfSidebarToggle';b.setAttribute('aria-controls','workbenchNav');b.innerHTML='<svg class="mi" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4h16v16H4V4zm2 2v12h3V6H6zm5 0v12h7V6h-7zm5 3-3 3 3 3V9z"/></svg><span>收起侧栏</span>';aside.querySelector('nav')?.after(b);const sync=()=>{const compact=document.body.classList.contains('sf-nav-compact');b.setAttribute('aria-expanded',String(!compact));b.setAttribute('aria-label',compact?'展开侧栏':'收起侧栏');b.title=compact?'展开侧栏':'收起侧栏';};try{document.body.classList.toggle('sf-nav-compact',localStorage.getItem('sfSidebarCompact')==='1')}catch{}sync();b.onclick=()=>{document.body.classList.toggle('sf-nav-compact');sync();try{localStorage.setItem('sfSidebarCompact',document.body.classList.contains('sf-nav-compact')?'1':'0')}catch{}};}
 // Split Showcase: same form, state and result nodes, paired on wide screens.
 const form=byId('quickForm'),out=byId('quickOutput');
 if(form&&out){const layout=document.createElement('div');layout.id='sfRequestLayout';const left=document.createElement('div');left.className='sf-request-input';form.before(layout);layout.append(left);left.append(form);for(const node of [byId('quickStatus'),byId('quickContinue')?.parentElement,byId('quickQueue')])if(node)left.append(node);layout.append(out);}
 for(const id of ['quickSubmit','mapsSubmit'])byId(id)?.classList.add('sf-discover');
 // Active Sessions: real queue entries, never sample sessions or invented uptime.
 const queue=byId('quickQueue');if(queue){const paint=()=>{for(const row of queue.children){const txt=row.textContent;row.dataset.sfState=/失败|取消|未执行/.test(txt)?'error':/已完成/.test(txt)?'done':/采集中|排队中|正在提交/.test(txt)?'busy':'idle';}};new MutationObserver(paint).observe(queue,{childList:true,subtree:true,characterData:true});paint();}
 // Status Bars + Text Stream: changed text arrives once, no looping important copy.
 for(const id of ['quickStatus','mapsStatus','ti-status']){const el=byId(id);if(el)new MutationObserver(()=>animate(el,'sf-text-enter')).observe(el,{childList:true,characterData:true,subtree:true});}
 const title=byId('pageTitle');if(title)new MutationObserver(()=>animate(title,'sf-flip')).observe(title,{childList:true,characterData:true,subtree:true});
 const archive=byId('overviewArchive');if(archive)new MutationObserver(()=>archive.querySelectorAll('strong').forEach(n=>animate(n,'sf-updated'))).observe(archive,{childList:true,characterData:true,subtree:true});
 // Draggable Marquee + Parallax Slider: finite source rail, with keyboard alternatives.
 const rail=document.querySelector('.source-entries'),hub=document.querySelector('.source-hub-head');
 if(rail&&hub){const controls=document.createElement('div');controls.className='sf-source-controls';controls.setAttribute('role','group');controls.setAttribute('aria-label','浏览数据来源');for(const [txt,label,direction]of [['‹','上一个来源',-1],['›','下一个来源',1]]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=txt;b.setAttribute('aria-label',label);b.onclick=()=>rail.scrollBy({left:direction*165,behavior:reduce()?'instant':'smooth'});controls.append(b)}hub.append(controls);let start=null,dragged=false;rail.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||rail.scrollWidth<=rail.clientWidth)return;start={x:e.clientX,scroll:rail.scrollLeft,id:e.pointerId};dragged=false;});rail.addEventListener('pointermove',e=>{if(!start)return;const delta=e.clientX-start.x;if(Math.abs(delta)>6){dragged=true;rail.scrollLeft=start.scroll-delta;}});const end=()=>{start=null};window.addEventListener('pointerup',end);rail.addEventListener('pointercancel',end);rail.addEventListener('click',e=>{if(dragged){e.preventDefault();e.stopImmediatePropagation();dragged=false;}},true);}
 // Art Gallery + Hover Image: layout preference, images still load only on explicit click.
 const rows=byId('resultRows');if(rows){const tools=document.createElement('div');tools.className='sf-gallery-tools';tools.hidden=true;tools.innerHTML='<span class="help">图片结果 · 点击“加载缩略图”预览</span><button type="button" class="secondary" data-sf-layout="list" aria-pressed="true">列表</button><button type="button" class="secondary" data-sf-layout="gallery" aria-pressed="false">画廊</button>';rows.before(tools);let layout='list';try{layout=localStorage.getItem('sfImageLayout')==='gallery'?'gallery':'list'}catch{}const apply=()=>{const any=!!rows.querySelector('.result.images'),all=any&&[...rows.querySelectorAll('.result')].every(e=>e.classList.contains('images'));tools.hidden=!all;rows.classList.toggle('sf-gallery',all&&layout==='gallery');for(const b of tools.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.sfLayout===layout));};tools.onclick=e=>{const b=e.target.closest('[data-sf-layout]');if(!b)return;layout=b.dataset.sfLayout;try{localStorage.setItem('sfImageLayout',layout)}catch{}apply();};new MutationObserver(apply).observe(rows,{childList:true});apply();}
 // Dashboard command shortcuts use the existing command dialog and normal routes.
 const dialog=byId('dataSearchDialog');if(dialog){const shortcuts=document.createElement('div');shortcuts.className='sf-shortcuts';shortcuts.innerHTML='<a href="#api">快速获取数据 ↗</a><a href="#maps">查找地图商家 ↗</a><a href="#results">浏览数据集 ↗</a>';dialog.append(shortcuts);shortcuts.addEventListener('click',e=>{if(e.target.closest('a'))dialog.close()});}
 const settings=byId('settingsView');if(settings){const p=document.createElement('div');p.className='panel';p.innerHTML='<h2>界面偏好</h2><label class="sf-motion-toggle"><input id="sfReduceMotion" type="checkbox">减少界面动效</label><p class="help">仅影响此浏览器的视觉效果；系统设置为减少动态效果时自动生效。</p>';settings.append(p);const check=byId('sfReduceMotion');try{check.checked=localStorage.getItem('sfReduceMotion')==='1'}catch{}document.body.classList.toggle('sf-reduced-motion',check.checked);check.onchange=()=>{document.body.classList.toggle('sf-reduced-motion',check.checked);try{localStorage.setItem('sfReduceMotion',check.checked?'1':'0')}catch{}};}
})();
'''


def extend(page: str) -> str:
    """Append once; keep every existing ID, handler and API contract intact."""
    if 'id="sfObsidianStyles"' in page:
        return page
    assert '</head>' in page and '</body>' in page
    page = page.replace('</head>', '<style id="sfObsidianStyles">'+CSS+'</style></head>', 1)
    return page.replace('</body>', '<script id="sfObsidianScript">'+JS+'</script></body>', 1)
